#!/bin/sh
# anyumbrelstore-nuvio-backend - one-shot init/maintenance job (runs on every
# app start, idempotent):
#
# 1. Clones/updates the pinned NuvioMedia/self-host revision into
#    ${APP_DATA_DIR}/data/self-host (upstream scripts, volumes, migrations).
# 2. Creates .env on first start (Umbrel LAN URLs + secrets generated by
#    upstream scripts/generate-secrets.sh) and keeps a backup copy so secrets
#    survive app updates that re-copy the app repo's data/ folder.
# 3. Regenerates ${APP_DATA_DIR}/data/nuvio.env: upstream .env plus an
#    auto-generated section with mapped variable names (GOTRUE_*, PGRST_*,
#    SERVICE_KEY, ...). Umbrel compose cannot interpolate the upstream
#    environment mappings from .env at app start, so the mapped names are
#    materialised here and consumed by all services via env_file.
set -eu

DATA_DIR=/app-data
REPO_DIR="$DATA_DIR/self-host"
UPSTREAM_REPO=https://github.com/NuvioMedia/self-host.git
PINNED_COMMIT="${NUVIO_SELFHOST_PINNED_COMMIT:?NUVIO_SELFHOST_PINNED_COMMIT not set}"
BACKUP_ENV="$DATA_DIR/nuvio-env.backup"
TARGET_ENV="$DATA_DIR/nuvio.env"

log() { echo "[nuvio-fetch] $*"; }
die() { echo "[nuvio-fetch] ERROR: $*" >&2; exit 1; }

set_env() {
    key=$1
    value=$2
    temp_env=$(mktemp "$REPO_DIR/.env.tmp.XXXXXX")
    found=0
    while IFS= read -r line || [ -n "$line" ]; do
        case "$line" in
            "$key="*) printf '%s=%s\n' "$key" "$value"; found=1 ;;
            *) printf '%s\n' "$line" ;;
        esac
    done < "$REPO_DIR/.env" > "$temp_env"
    [ "$found" -eq 0 ] && printf '%s=%s\n' "$key" "$value" >> "$temp_env"
    chmod 600 "$temp_env"
    mv "$temp_env" "$REPO_DIR/.env"
}

is_placeholder() {
    [ -f "$1" ] || return 0
    head -n 1 "$1" | grep -q '^# placeholder' && return 0
    return 1
}

# --- 1) upstream checkout at the pinned revision --------------------------
if [ ! -d "$REPO_DIR/.git" ]; then
    mkdir -p "$REPO_DIR"
    git -C "$REPO_DIR" init -q
    git -C "$REPO_DIR" remote add origin "$UPSTREAM_REPO"
fi
log "fetching $UPSTREAM_REPO @ $PINNED_COMMIT"
git -C "$REPO_DIR" fetch -q --depth 1 origin "$PINNED_COMMIT"
git -C "$REPO_DIR" checkout -q --force FETCH_HEAD

mkdir -p "$REPO_DIR/volumes/db/data"
chmod 700 "$REPO_DIR/volumes/db/data"

# --- 2) .env lifecycle -----------------------------------------------------
# nuvio.env is the shipped placeholder on a fresh install, or after an app
# update re-copied the repo's data/ folder. Restore secrets from the backup
# copy in that case (the backup itself is never shipped in the repo).
if is_placeholder "$TARGET_ENV" && [ -f "$BACKUP_ENV" ]; then
    log "restoring .env from backup (secrets survive app updates)"
    cp "$BACKUP_ENV" "$REPO_DIR/.env"
    chmod 600 "$REPO_DIR/.env"
fi

if [ ! -f "$REPO_DIR/.env" ]; then
    log "first start: creating .env with Umbrel defaults and secrets"
    cp "$REPO_DIR/.env.example" "$REPO_DIR/.env"
    chmod 600 "$REPO_DIR/.env"
    set_env SUPABASE_PUBLIC_URL http://umbrel.local:30123
    set_env API_EXTERNAL_URL http://umbrel.local:30123
    set_env SITE_URL http://umbrel.local:30122
    set_env ADDITIONAL_REDIRECT_URLS http://umbrel.local:30122
    set_env WEBAUTHN_RP_ORIGINS http://umbrel.local:30122
    set_env MAILER_EXTERNAL_HOSTS umbrel.local
    sh "$REPO_DIR/scripts/generate-secrets.sh"
fi

cp "$REPO_DIR/.env" "$BACKUP_ENV"
chmod 600 "$BACKUP_ENV"

# --- 3) regenerate nuvio.env (upstream .env + mapped vars) -----------------
# Parse .env without sourcing it: values may contain spaces (e.g.
# STUDIO_DEFAULT_ORGANIZATION), which sourcing would execute as commands.
while IFS= read -r line || [ -n "$line" ]; do
    case "$line" in
        *=*)
            env_key=${line%%=*}
            env_value=${line#*=}
            # export only sane variable names (defense in depth)
            if [ -n "$env_key" ] && [ -z "$(printf '%s' "$env_key" | tr -d 'A-Za-z0-9_')" ]; then
                export "$env_key=$env_value"
            fi
            ;;
    esac
done < "$REPO_DIR/.env"

case "${POSTGRES_PASSWORD:-}" in
    ""|generate-me) die "POSTGRES_PASSWORD missing - secrets were not generated" ;;
esac
case "${JWT_SECRET:-}" in
    ""|generate-me) die "JWT_SECRET missing - secrets were not generated" ;;
esac
[ -n "${ANON_KEY:-}" ] || die "ANON_KEY missing"
[ -n "${SERVICE_ROLE_KEY:-}" ] || die "SERVICE_ROLE_KEY missing"

# JWKS: upstream maps ${JWT_JWKS:-${JWT_SECRET}} for PostgREST and
# ${JWT_JWKS:-{"keys":[]}} for Storage. Persist valid JSON for both cases.
if [ -n "${JWT_JWKS:-}" ]; then
    PGRST_JWT_SECRET_VALUE=$JWT_JWKS
else
    PGRST_JWT_SECRET_VALUE=$JWT_SECRET
    set_env JWT_JWKS '{"keys":[]}'
fi

cp "$REPO_DIR/.env" "$TARGET_ENV"

cat >> "$TARGET_ENV" <<EOF
# --- ANYUMBRELSTORE-MAPPED-ENV-BEGIN (auto-generated by nuvio-fetch) ---
# The upstream compose file maps these variable names from the values above
# via compose interpolation. This app generates them at start time instead.

# db
PGPORT=${POSTGRES_PORT}
PGPASSWORD=${POSTGRES_PASSWORD}
PGDATABASE=${POSTGRES_DB}
JWT_EXP=${JWT_EXPIRY}

# auth (GoTrue)
GOTRUE_API_HOST=0.0.0.0
GOTRUE_API_PORT=9999
GOTRUE_DB_DRIVER=postgres
GOTRUE_DB_DATABASE_URL=postgres://supabase_auth_admin:${POSTGRES_PASSWORD}@${POSTGRES_HOST}:${POSTGRES_PORT}/${POSTGRES_DB}
GOTRUE_DB_MAX_POOL_SIZE=60
GOTRUE_DB_MAX_IDLE_POOL_SIZE=30
GOTRUE_DB_CONN_MAX_LIFETIME=10m
GOTRUE_DB_CONN_MAX_IDLE_TIME=2m
GOTRUE_SITE_URL=${SITE_URL}
GOTRUE_URI_ALLOW_LIST=${ADDITIONAL_REDIRECT_URLS}
GOTRUE_DISABLE_SIGNUP=${DISABLE_SIGNUP}
GOTRUE_JWT_ADMIN_ROLES=service_role
GOTRUE_JWT_AUD=authenticated
GOTRUE_JWT_DEFAULT_GROUP_NAME=authenticated
GOTRUE_JWT_EXP=${JWT_EXPIRY}
GOTRUE_JWT_SECRET=${JWT_SECRET}
GOTRUE_JWT_KEYS=${JWT_KEYS:-[]}
GOTRUE_JWT_ISSUER=${API_EXTERNAL_URL}/auth/v1
GOTRUE_EXTERNAL_EMAIL_ENABLED=${ENABLE_EMAIL_SIGNUP}
GOTRUE_EXTERNAL_ANONYMOUS_USERS_ENABLED=${ENABLE_ANONYMOUS_USERS}
GOTRUE_MAILER_AUTOCONFIRM=${ENABLE_EMAIL_AUTOCONFIRM}
GOTRUE_MAILER_SECURE_EMAIL_CHANGE_ENABLED=${MAILER_SECURE_EMAIL_CHANGE_ENABLED}
GOTRUE_MAILER_EXTERNAL_HOSTS=${MAILER_EXTERNAL_HOSTS}
GOTRUE_PASSWORD_MIN_LENGTH=${PASSWORD_MIN_LENGTH}
GOTRUE_SECURITY_REFRESH_TOKEN_ROTATION_ENABLED=${AUTH_REFRESH_TOKEN_ROTATION_ENABLED}
GOTRUE_SECURITY_REFRESH_TOKEN_REUSE_INTERVAL=${AUTH_REFRESH_TOKEN_REUSE_INTERVAL}
GOTRUE_RATE_LIMIT_TOKEN_REFRESH=${RATE_LIMIT_TOKEN_REFRESH}
GOTRUE_RATE_LIMIT_ANONYMOUS_USERS=${RATE_LIMIT_ANONYMOUS_USERS}
GOTRUE_RATE_LIMIT_VERIFY=${RATE_LIMIT_VERIFY}
GOTRUE_RATE_LIMIT_HEADER=${RATE_LIMIT_HEADER}
GOTRUE_PASSKEY_ENABLED=${PASSKEY_ENABLED}
GOTRUE_WEBAUTHN_RP_ID=${WEBAUTHN_RP_ID}
GOTRUE_WEBAUTHN_RP_DISPLAY_NAME=${WEBAUTHN_RP_DISPLAY_NAME}
GOTRUE_WEBAUTHN_RP_ORIGINS=${WEBAUTHN_RP_ORIGINS}
GOTRUE_SMTP_ADMIN_EMAIL=${SMTP_ADMIN_EMAIL}
GOTRUE_SMTP_HOST=${SMTP_HOST}
GOTRUE_SMTP_PORT=${SMTP_PORT}
GOTRUE_SMTP_USER=${SMTP_USER}
GOTRUE_SMTP_PASS=${SMTP_PASS}
GOTRUE_SMTP_SENDER_NAME=${SMTP_SENDER_NAME}
GOTRUE_MAILER_URLPATHS_INVITE=${MAILER_URLPATHS_INVITE}
GOTRUE_MAILER_URLPATHS_CONFIRMATION=${MAILER_URLPATHS_CONFIRMATION}
GOTRUE_MAILER_URLPATHS_RECOVERY=${MAILER_URLPATHS_RECOVERY}
GOTRUE_MAILER_URLPATHS_EMAIL_CHANGE=${MAILER_URLPATHS_EMAIL_CHANGE}
GOTRUE_EXTERNAL_PHONE_ENABLED=${ENABLE_PHONE_SIGNUP}
GOTRUE_SMS_AUTOCONFIRM=${ENABLE_PHONE_AUTOCONFIRM}
GOTRUE_MFA_TOTP_ENROLL_ENABLED=${MFA_TOTP_ENROLL_ENABLED}
GOTRUE_MFA_TOTP_VERIFY_ENABLED=${MFA_TOTP_VERIFY_ENABLED}
GOTRUE_MFA_MAX_ENROLLED_FACTORS=${MFA_MAX_ENROLLED_FACTORS}

# rest (PostgREST)
PGRST_DB_URI=postgres://authenticator:${POSTGRES_PASSWORD}@${POSTGRES_HOST}:${POSTGRES_PORT}/${POSTGRES_DB}
PGRST_DB_ANON_ROLE=anon
PGRST_JWT_SECRET=${PGRST_JWT_SECRET_VALUE}
PGRST_DB_USE_LEGACY_GUCS=false
PGRST_APP_SETTINGS_JWT_SECRET=${JWT_SECRET}
PGRST_APP_SETTINGS_JWT_EXP=${JWT_EXPIRY}
PGRST_ADMIN_SERVER_PORT=3001
PGRST_ADMIN_SERVER_HOST=localhost

# storage (Storage API)
SERVICE_KEY=${SERVICE_ROLE_KEY}
AUTH_JWT_SECRET=${JWT_SECRET}
DATABASE_URL=postgres://supabase_storage_admin:${POSTGRES_PASSWORD}@${POSTGRES_HOST}:${POSTGRES_PORT}/${POSTGRES_DB}
STORAGE_PUBLIC_URL=${SUPABASE_PUBLIC_URL}
POSTGREST_URL=http://rest:3000
REQUEST_ALLOW_X_FORWARDED_PATH=true
FILE_SIZE_LIMIT=52428800
STORAGE_BACKEND=file
FILE_STORAGE_BACKEND_PATH=/var/lib/storage
TENANT_ID=${STORAGE_TENANT_ID}
ENABLE_IMAGE_TRANSFORMATION=true
IMGPROXY_URL=http://imgproxy:5001

# imgproxy
IMGPROXY_BIND=:5001
IMGPROXY_LOCAL_FILESYSTEM_ROOT=/
IMGPROXY_USE_ETAG=true
IMGPROXY_MAX_SRC_RESOLUTION=16.8

# functions (edge-runtime)
SUPABASE_URL=http://kong:8000
SUPABASE_ANON_KEY=${ANON_KEY}
SUPABASE_SERVICE_ROLE_KEY=${SERVICE_ROLE_KEY}
SUPABASE_PUBLISHABLE_KEYS={"default":""}
SUPABASE_SECRET_KEYS={"default":""}
SUPABASE_DB_URL=postgresql://postgres:${POSTGRES_PASSWORD}@${POSTGRES_HOST}:${POSTGRES_PORT}/${POSTGRES_DB}
VERIFY_JWT=${FUNCTIONS_VERIFY_JWT}

# kong (declarative config templating)
SUPABASE_ANON_KEY=${ANON_KEY}
SUPABASE_SERVICE_KEY=${SERVICE_ROLE_KEY}

# account-dashboard
NUVIO_SUPABASE_URL=${SUPABASE_PUBLIC_URL}
NUVIO_SUPABASE_ANON_KEY=${ANON_KEY}
# --- ANYUMBRELSTORE-MAPPED-ENV-END ---
EOF

chmod 600 "$TARGET_ENV"
log "nuvio.env written (backend: ${SUPABASE_PUBLIC_URL}, dashboard: ${SITE_URL})"
